-- El juego de caracteres se fija SIEMPRE: el cliente mysql lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;

-- ================================================================================================
-- Espacios Abiertos e Islas del Mar Menor · Fase 3 (N3): puntos de interés.
--
-- GENERADO por Tools/catalogo-nacional/build-poi-sql.js desde el bloque `pointsOfInterest` de
-- Frontend/Data/parks/murcia/espacios-abiertos-e-islas-del-mar-menor/park.json. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-poi-sql.js --park espacios-abiertos-e-islas-del-mar-menor
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado: en un
-- despliegue con backend, sin este SQL el espacio se seguiría sirviendo con 0 puntos de interés.
--
-- ANTES DE APLICAR, comprobar que el espacio tiene fila en `parks`. Si no la tiene, el
-- INSERT ... SELECT de abajo no encuentra nada y **carga cero filas sin dar ningún error** (le pasó
-- a Sierra Espuña el 2026-08-08):
--   SELECT id, slug, name FROM parks WHERE slug = 'espacios-abiertos-e-islas-del-mar-menor';
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre la clave única (park_id, slug). Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database/n3-pois-espacios-abiertos-e-islas-del-mar-menor.sql
-- ================================================================================================

-- 9 punto(s) de interés.
INSERT INTO points_of_interest (park_id, slug, name, type, description, latitude, longitude, image_url, source, is_approx)
SELECT p.id, poi.slug, poi.name, poi.type, poi.description, poi.latitude, poi.longitude, poi.image_url, poi.source, poi.is_approx
FROM parks p
JOIN (
    SELECT 'cabezo-del-carmoli' slug, 'Cabezo del Carmolí' name, 'Geológico' type, 'Cerro volcánico de 112 m que se levanta solo sobre la llanura, en la orilla misma de la laguna. El plan de gestión lo señala como uno de los hitos paisajísticos del Mar Menor y le reconoce interés geológico, geomorfológico y paleontológico: es uno de los afloramientos volcánicos que jalonan esta costa, la misma roca de la que están hechas las islas de la laguna. Se sube por el Sendero Natural Cabezo de El Carmolí, peatonal, que arranca del acceso de la carretera RM-F54; por el sur y el oeste lo rodean cultivos de secano y por el norte la urbanización trepa por la ladera.' description, 37.687466 latitude, -0.842823 longitude, NULL image_url, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» —«El Cabezo del Carmolí, de origen volcánico… constituyen elevaciones rocosas que destacan sobre la llanura meridional de la Cuenca del Mar Menor como hitos paisajísticos de excepcional interés»— y §2.1.4 «Elementos clave», que lo enumera «por representar o contener elementos de interés geológico, geomorfológico y paleontológico». Su acceso y su sendero constan en las Tablas 156 y 157 del §2.1.6.3.1. Coordenada exacta: nodo de la cima etiquetado como volcán en OpenStreetMap (node/387506706).' source, FALSE is_approx
    UNION ALL
    SELECT 'cabezo-de-san-gines', 'Cabezo de San Ginés', 'Paisajístico', 'Elevación rocosa entre El Beal y El Estrecho de San Ginés, con panorámica sobre el Mar Menor desde el collado. El plan la nombra elemento clave del espacio junto a las islas y al Carmolí. Su entorno está muy transformado por la minería subterránea antigua, cuyos restos —bocas de respiraderos, movimientos de tierra y pequeñas construcciones abandonadas— se ven por toda la ladera. La senda que sube desde el límite norte del Estrecho no está señalizada ni delimitada y se difumina pasado el collado; es la que siguen los romeros de San Ginés hasta las ermitas del Monte Miral.', 37.635418, -0.827157, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.4 «Elementos clave» y §2.1.6.2.5, que describe la senda al collado, la romería y los restos mineros. El acceso desde la carretera RM-F43 y el aparcamiento de Las Victorias constan en la Tabla 156 del §2.1.6.3.1. Coordenada exacta: nodo de la cima en OpenStreetMap (node/1304132100). AVISO recogido del propio plan: la senda no está señalizada ni delimitada, y la ladera conserva bocas de mina abiertas.', FALSE
    UNION ALL
    SELECT 'playa-de-la-hita', 'Playa de la Hita', 'Natural', 'Humedal del extremo norte de la laguna, con un conjunto de charcas pequeñas y un criptohumedal —agua dulce que circula bajo la arena sin llegar a asomar—. Lo que más ocupa son los carrizales, los almarjales y los saladares; los arenales quedan en una franja estrecha pegada a la costa. En el sector más septentrional el carrizal se interna unos metros dentro de la laguna, un paisaje ribereño que no se repite en el resto del Mar Menor. Es además una de las pocas localidades donde crece Artemisia gallica. Se recorre por el Sendero Natural Humedal de La Hita, peatonal y ciclista.', 37.764947, -0.820579, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» y Tabla 149 del §2.1.2.5, que lo declara Lugar de Interés Botánico de la Región de Murcia: «Zona de arenal y saladar litoral dominado por matorral halófilo acompañado de carrizal. Una de las pocas localidades donde se puede encontrar Artemisia gallica». Su acceso desde la carretera RM-F34 y su sendero constan en las Tablas 156 y 157. Coordenada aproximada: centro del humedal cartografiado en OpenStreetMap (way/1313755854), no un punto medido, porque el elemento es una superficie.', TRUE
    UNION ALL
    SELECT 'marina-del-carmoli', 'Marina del Carmolí', 'Natural', 'Saladar extenso al pie del cabezo del mismo nombre, y uno de los mejores albardinales que quedan en la ribera del Mar Menor. Junto a la costa hay arenales húmedos y charcas litorales pequeñas, y hacia el interior la matriz de saladar da paso a una estepa salina de albardín salpicada de manchas de carrizal. Buena parte del recinto estuvo vallado por haber sido del Ministerio de Defensa, y ese cierre —hoy discontinuo— es una de las razones de que se conserve. Se recorre por el Sendero Natural Marina del Carmolí, peatonal y ciclista.', 37.701528, -0.854837, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» —«los arenales húmedos y las pequeñas charcas litorales inmersas en una matriz de saladar dan paso, hacia el interior, a una extensa estepa salina o albardinal»— y §2.1.6.2.2, que describe el vallado militar, los tres aparcamientos de la carretera RM-F54 y el área de acogida del GR-92 en Bocarrambla. Acceso y sendero en las Tablas 156 y 157. Coordenada aproximada: centro del humedal cartografiado en OpenStreetMap (relation/17985991), no un punto medido, porque el elemento es una superficie.', TRUE
    UNION ALL
    SELECT 'saladar-de-lo-poyo', 'Saladar de Lo Poyo', 'Natural', 'Saladar organizado en bandas paralelas a la costa: primero la franja de arena, después los restos de unas salinas antiguas y detrás las matrices de saladar y carrizal, todo ello cortado en perpendicular por los cauces de las ramblas del Beal y de Ponce, que bajan desde la sierra minera. Es uno de los escasos puntos del litoral donde aparecen a la vez la zanahoria marina (Echinophora spinosa) y la esparraguera de dunas, y por eso el plan lo declara Lugar de Interés Botánico. Por el borde oriental empiezan ya los cultivos de regadío.', 37.661392, -0.812665, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» y Tabla 149 del §2.1.2.5, que lo declara Lugar de Interés Botánico de la Región de Murcia: «Arenal y formación dunar litoral dominada por especies típicas de saladar y arenal. Una de las escasas zonas del litoral en la que aparece Echinophora spinosa y Asparagus maritimus». Coordenada aproximada: centro del saladar cartografiado en OpenStreetMap (way/1312590923), no un punto medido, porque el elemento es una superficie.', TRUE
    UNION ALL
    SELECT 'salinas-de-marchamalo', 'Salinas de Marchamalo', 'Natural', 'Estanques salineros al sur de la laguna, entre saladares, juncales y arenales. La lámina de agua de los estanques es el elemento que da carácter al paisaje de este sector y lo que atrae a las limícolas y a los flamencos, que encuentran aquí una salinidad y una profundidad que la laguna abierta no les da. El plan prevé un sendero entre Playa Paraíso y el observatorio de aves, peatonal y ciclista, y el acceso se hace desde la RM-12.', 37.635208, -0.720662, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» —«los elementos paisajísticos más peculiares son la lámina de agua de los estanques salineros, que destaca entre los saladares, juncales y arenales»— y Tablas 156 y 157 del §2.1.6.3.1 (acceso desde la RM-12; «Sendero Salinas de Marchamalo (Playa Paraíso – observatorio)»). Coordenada aproximada: centro del recinto salinero cartografiado en OpenStreetMap (relation/2015502, con el topónimo escrito «Salinas de Machamalo»), no un punto medido, porque el elemento es una superficie.', TRUE
    UNION ALL
    SELECT 'playa-de-las-amoladeras', 'Playa de las Amoladeras', 'Natural', 'Arenal amplio en el arranque de La Manga, que no se queda en la orilla: se extiende tierra adentro cruzando la carretera de La Manga hasta llegar casi a los estanques cristalizadores de las salinas de Marchamalo. Esa continuidad entre playa, duna y saladar es lo que lo distingue del resto de playas del Mar Menor, donde el paseo marítimo corta la secuencia. Tiene dos accesos peatonales desde la autovía de La Manga.', 37.639473, -0.707877, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.3 «Descripción del paisaje» —«la Playa de las Amoladeras conforma una gran matriz arenosa que se extiende desde la línea de costa a la carretera de La Manga y más allá de ésta, hasta las inmediaciones de los estanques cristalizadores de las salinas»— y Tabla 156 del §2.1.6.3.1 (dos accesos peatonales desde la Autovía de La Manga). Coordenada aproximada: centro del arenal cartografiado en OpenStreetMap (relation/3974792). Cae 4 m FUERA del límite oficial, dentro del margen de tolerancia con el que se admite un punto representativo de una superficie que sí está dentro.', TRUE
    UNION ALL
    SELECT 'isla-perdiguera', 'Isla Perdiguera', 'Natural', 'La segunda isla en tamaño de la laguna y la más visitada de todas, con embarcadero y un sendero natural que va del muelle a la salida del túnel. Como las demás islas del Mar Menor es un afloramiento volcánico cubierto de matorral, interrumpido solo por las manchas de playa, acantilado y roquedo. En su vertiente oeste, junto a la playa, quedan los restos abandonados de varias edificaciones; las instalaciones de restauración que la hicieron famosa eran ilegales y las demolió Costas en 2007 por orden judicial. Solo se llega en barco.', 37.699852, -0.800291, 'https://commons.wikimedia.org/wiki/Special:FilePath/La_Esparte%C3%B1a_(Isla_Perdiguera).jpg?width=1280', 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.6.2.7 «Islas del Mar Menor» —que la describe como «la isla más visitada del Mar Menor» y relata la demolición de 2007— y §2.1.3, que caracteriza las islas como «afloramientos volcánicos que destacan como hitos paisajísticos de excepcional interés». El acceso en embarcación con muelle o embarcadero y el «Sendero Natural Isla Perdiguera (Embarcadero – salida túnel)» constan en las Tablas 156 y 157. Coordenada aproximada: centro de la isla cartografiada en OpenStreetMap (way/4787120). Cae 16 m FUERA del límite oficial, dentro del margen de tolerancia con el que se admite un punto representativo de una superficie que sí está dentro; Wikimedia Commons (foto: Juan Antonio de la Puente, CC BY-SA 4.0)', TRUE
    UNION ALL
    SELECT 'isla-del-ciervo', 'Isla del Ciervo', 'Natural', 'Isla volcánica frente a La Manga con el matorral litoral mejor conservado de la laguna: palmitar y cornical en densidades altas, varios grupos de chumberillo de lobo y uno de los dos únicos enclaves de toda la Región donde crece Ranunculus bullatus. El plan la declara Lugar de Interés Botánico por ese conjunto. Como el resto de las islas, es un afloramiento volcánico bajo una matriz de matorral, interrumpida solo por playas, acantilados y roquedos.', 37.660388, -0.737157, NULL, 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, Tabla 149 del §2.1.2.5, que la declara Lugar de Interés Botánico de la Región de Murcia: «Matorral litoral en buen estado de conservación, con importantes densidades de palmitar y cornical. Varios grupos de Caralluma europaea. Uno de los dos únicos enclaves de la Región con Ranunculus bullatus»; y §2.1.3, que caracteriza las islas como afloramientos volcánicos. Coordenada aproximada: centro de la isla cartografiada en OpenStreetMap (way/4787114), no un punto medido, porque el elemento es una superficie.', TRUE
) poi
WHERE p.slug = 'espacios-abiertos-e-islas-del-mar-menor'
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    type = VALUES(type),
    description = VALUES(description),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude),
    image_url = VALUES(image_url),
    source = VALUES(source),
    is_approx = VALUES(is_approx);

-- Comprobación posterior: debe devolver 9.
SELECT COUNT(*) AS pois_cargados FROM points_of_interest poi
JOIN parks p ON p.id = poi.park_id WHERE p.slug = 'espacios-abiertos-e-islas-del-mar-menor';
